using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using FluentAssertions;
using Xunit;

namespace Game.Core.Tests.Tasks;

public sealed class Task111SplitIntegrationTests
{
    private const int TaskId = 111;
    private const int SplitTask149 = 149;
    private const int SplitTask150 = 150;
    private const string Task111Ref = "Game.Core.Tests/Tasks/Task111SplitIntegrationTests.cs";
    private const string Task52Ref = "Game.Core.Tests/Tasks/Task52TurnPhaseWindowTests.cs";
    private const string DiceFlowRef = "Tests.Godot/tests/Scenes/Sanguo/test_sanguo_game_loop_dice_flow.gd";
    private const string SplitTask149Ref = "Game.Core.Tests/Tasks/Task149CampaignBossVictoryScenarioTests.cs";
    private const string SplitTask150Ref = "Game.Core.Tests/Tasks/Task150CampaignCampFailScenarioTests.cs";

    private static readonly string[] ViewFiles =
    {
        "tasks_back.json",
        "tasks_gameplay.json",
    };

    // ACC:T111.1
    [Fact]
    [Trait("acceptance", "ACC:T111.1")]
    public void ShouldBindTask111AcceptanceToTaskScopedIntegrationEvidence_WhenLoadingTaskViews()
    {
        var repoRoot = FindRepoRoot();

        foreach (var viewFile in ViewFiles)
        {
            var task = GetTaskByTaskmasterId(repoRoot, viewFile, TaskId);
            var acceptance = ReadStringArray(task, "acceptance");
            var testRefs = ReadStringArray(task, "test_refs");
            var task149Refs = ReadTaskTestRefs(repoRoot, viewFile, SplitTask149);
            var task150Refs = ReadTaskTestRefs(repoRoot, viewFile, SplitTask150);

            acceptance.Should().HaveCount(2);
            acceptance[0].Should().Contain("split tasks 149 and 150");
            acceptance[0].Should().Contain("verified by deterministic acceptance evidence");
            acceptance[0].Should().Contain("not accepted if either split task lacks closure evidence");
            acceptance[1].Should().Contain("scope is limited to integration closure of split-task evidence");
            acceptance[1].Should().Contain("independent implementation belongs to split tasks 149 and 150");
            acceptance[1].Should().Contain("must not be introduced here");

            testRefs.Should().Contain(Task111Ref);
            testRefs.Should().Contain(Task52Ref);
            testRefs.Should().Contain(DiceFlowRef);
            task149Refs.Should().Contain(SplitTask149Ref);
            task150Refs.Should().Contain(SplitTask150Ref);

            File.Exists(Path.Combine(repoRoot, SplitTask149Ref.Replace('/', Path.DirectorySeparatorChar)))
                .Should().BeTrue("split task 149 evidence test must exist");
            File.Exists(Path.Combine(repoRoot, SplitTask150Ref.Replace('/', Path.DirectorySeparatorChar)))
                .Should().BeTrue("split task 150 evidence test must exist");
        }
    }

    // ACC:T111.2
    [Fact]
    [Trait("acceptance", "ACC:T111.2")]
    public void ShouldKeepTask111ScopeClosureOnly_WhenReadingAcceptanceContracts()
    {
        var repoRoot = FindRepoRoot();

        foreach (var viewFile in ViewFiles)
        {
            var task = GetTaskByTaskmasterId(repoRoot, viewFile, TaskId);
            var acceptance = ReadStringArray(task, "acceptance");

            acceptance.Should().HaveCount(2);
            acceptance[1].Should().Contain("scope is limited to integration closure of split-task evidence");
            acceptance[1].Should().Contain("independent implementation belongs to split tasks 149 and 150");
            acceptance[1].Should().Contain("must not be introduced here");
        }
    }

    // ACC:T111.1
    [Fact]
    [Trait("acceptance", "ACC:T111.1")]
    public void ShouldCloseIntegration_WhenBothSplitTaskEvidencesAreCompleted()
    {
        var task149Evidence = new SplitClosureEvidence(
            SplitTask149,
            SplitTask149Ref,
            "campaign-endgame-v3",
            IsCompleted: true);
        var task150Evidence = new SplitClosureEvidence(
            SplitTask150,
            SplitTask150Ref,
            "campaign-endgame-v3",
            IsCompleted: true);

        var outcome = Task111SplitIntegrationPack.Evaluate(task149Evidence, task150Evidence);

        outcome.IsClosed.Should().BeTrue();
        outcome.FailureCode.Should().BeNull();
        outcome.ClosureCode.Should().Be("campaign-endgame-v3");
    }

    // ACC:T111.1
    [Fact]
    [Trait("acceptance", "ACC:T111.1")]
    public void ShouldRemainOpen_WhenEitherSplitTaskEvidenceIsMissing()
    {
        var task149Evidence = new SplitClosureEvidence(
            SplitTask149,
            SplitTask149Ref,
            "campaign-endgame-v3",
            IsCompleted: true);

        var outcome = Task111SplitIntegrationPack.Evaluate(task149Evidence);

        outcome.IsClosed.Should().BeFalse();
        outcome.FailureCode.Should().Be("MISSING_SPLIT_TASK_EVIDENCE");
    }

    // ACC:T111.1
    [Fact]
    [Trait("acceptance", "ACC:T111.1")]
    public void ShouldRemainOpen_WhenSplitTaskEvidenceSignaturesDoNotMatch()
    {
        var task149Evidence = new SplitClosureEvidence(
            SplitTask149,
            SplitTask149Ref,
            "campaign-endgame-v3",
            IsCompleted: true);
        var task150Evidence = new SplitClosureEvidence(
            SplitTask150,
            SplitTask150Ref,
            "campaign-endgame-v3-with-drift",
            IsCompleted: true);

        var outcome = Task111SplitIntegrationPack.Evaluate(task149Evidence, task150Evidence);

        outcome.IsClosed.Should().BeFalse();
        outcome.FailureCode.Should().Be("MISMATCHED_CLOSURE_SIGNATURE");
    }

    private static string FindRepoRoot()
    {
        var current = new DirectoryInfo(AppContext.BaseDirectory);
        while (current is not null)
        {
            var marker = Path.Combine(current.FullName, ".taskmaster", "tasks", "tasks.json");
            if (File.Exists(marker))
            {
                return current.FullName;
            }

            current = current.Parent;
        }

        throw new DirectoryNotFoundException("Repo root not found (missing .taskmaster/tasks/tasks.json).");
    }

    private static JsonElement GetTaskByTaskmasterId(string repoRoot, string fileName, int taskmasterId)
    {
        using var doc = LoadJson(repoRoot, ".taskmaster", "tasks", fileName);
        foreach (var task in doc.RootElement.EnumerateArray())
        {
            if (task.TryGetProperty("taskmaster_id", out var idProperty) &&
                idProperty.ValueKind == JsonValueKind.Number &&
                idProperty.TryGetInt32(out var idValue) &&
                idValue == taskmasterId)
            {
                return task.Clone();
            }
        }

        throw new InvalidOperationException($"Task {taskmasterId} not found in {fileName}.");
    }

    private static string[] ReadTaskTestRefs(string repoRoot, string fileName, int taskmasterId)
    {
        var task = GetTaskByTaskmasterId(repoRoot, fileName, taskmasterId);
        return ReadStringArray(task, "test_refs");
    }

    private static string[] ReadStringArray(JsonElement task, string propertyName)
    {
        task.TryGetProperty(propertyName, out var value).Should().BeTrue($"Task {TaskId} must define '{propertyName}'.");
        value.ValueKind.Should().Be(JsonValueKind.Array);
        return value.EnumerateArray().Select(static item => item.GetString() ?? string.Empty).ToArray();
    }

    private static JsonDocument LoadJson(string repoRoot, params string[] parts)
    {
        var path = Path.Combine(new[] { repoRoot }.Concat(parts).ToArray());
        return JsonDocument.Parse(File.ReadAllText(path));
    }

    private sealed record SplitClosureEvidence(
        int SplitTaskId,
        string SourcePath,
        string ClosureSignature,
        bool IsCompleted);

    private sealed record ClosureOutcome(bool IsClosed, string ClosureCode, string? FailureCode);

    private static class Task111SplitIntegrationPack
    {
        public static ClosureOutcome Evaluate(params SplitClosureEvidence[] evidences)
        {
            evidences.Should().NotBeNull();
            evidences.Should().NotBeEmpty();

            if (evidences.Any(static item => !item.IsCompleted))
            {
                return new ClosureOutcome(false, string.Empty, "INCOMPLETE_SPLIT_TASK_EVIDENCE");
            }

            if (evidences.Any(static item => !IsTaskScopedTestPath(item.SourcePath)))
            {
                return new ClosureOutcome(false, string.Empty, "NON_TEST_EVIDENCE_PATH");
            }

            var evidenceTasks = evidences.Select(static item => item.SplitTaskId).ToHashSet();
            if (!evidenceTasks.Contains(SplitTask149) || !evidenceTasks.Contains(SplitTask150))
            {
                return new ClosureOutcome(false, string.Empty, "MISSING_SPLIT_TASK_EVIDENCE");
            }

            var signatures = evidences
                .Select(static item => item.ClosureSignature)
                .Where(static item => !string.IsNullOrWhiteSpace(item))
                .Distinct(StringComparer.Ordinal)
                .ToArray();
            if (signatures.Length != 1)
            {
                return new ClosureOutcome(false, string.Empty, "MISMATCHED_CLOSURE_SIGNATURE");
            }

            return new ClosureOutcome(true, signatures[0], null);
        }

        private static bool IsTaskScopedTestPath(string path)
        {
            if (string.IsNullOrWhiteSpace(path))
            {
                return false;
            }

            var normalized = path.Replace('\\', '/');
            return normalized.StartsWith("Game.Core.Tests/Tasks/Task", StringComparison.Ordinal);
        }
    }
}

using System.Linq;
using FluentAssertions;
using Xunit;

namespace Game.Core.Tests.Tasks;

public sealed class Task151SplitClosureTests
{
    // ACC:T151.2
    [Fact]
    public void ShouldRejectClosure_WhenAnyRequiredSplitTaskEvidenceIsMissing()
    {
        var requiredTaskIds = new[] { 173, 174, 175 };
        var providedEvidenceTaskIds = new[] { 173, 174 };
        var sut = new SplitClosureHardGate(requiredTaskIds);

        var result = sut.Evaluate(providedEvidenceTaskIds);

        result.IsClosable.Should().BeFalse("closure must not pass when any required split-task evidence is missing");
    }

    [Fact]
    public void ShouldNotAdvanceStage_WhenAnyRequiredSplitTaskEvidenceIsMissing()
    {
        var requiredTaskIds = new[] { 173, 174, 175 };
        var providedEvidenceTaskIds = new[] { 173, 175 };
        var sut = new SplitClosureHardGate(requiredTaskIds);

        var result = sut.Evaluate(providedEvidenceTaskIds);

        result.AdvanceAllowed.Should().BeFalse("closure must not advance when split-task evidence is incomplete");
    }

    private sealed class SplitClosureHardGate
    {
        private readonly int[] requiredTaskIds;

        public SplitClosureHardGate(int[] requiredTaskIds)
        {
            this.requiredTaskIds = requiredTaskIds;
        }

        public HardGateResult Evaluate(int[] providedEvidenceTaskIds)
        {
            var requiredDistinct = requiredTaskIds.Distinct().ToArray();
            var providedDistinct = providedEvidenceTaskIds.Distinct().ToArray();
            var matchedCount = requiredDistinct.Intersect(providedDistinct).Count();
            var passes = matchedCount == requiredDistinct.Length;
            return new HardGateResult(passes, passes);
        }
    }

    private readonly record struct HardGateResult(bool IsClosable, bool AdvanceAllowed);
}

using System;
using System.Collections.Generic;
using System.Linq;
using FluentAssertions;
using Game.Core.Services.Sanguo;
using Xunit;

namespace Game.Core.Tests.Tasks;

public sealed class Task151SplitIntegrationTests
{
    private static readonly int[] RequiredSplitTaskIds = { 173, 174, 175 };

    private static readonly string[] RequiredAssertionIds =
    {
        "A-013",
        "A-014",
        "A-015",
        "A-016",
        "A-017",
        "A-018",
        "A-019",
        "A-020",
    };

    // ACC:T151.1
    [Fact]
    public void ShouldExposeSplitTaskOwnership_WhenRunningCoreHardGateClosure()
    {
        var pack = new Task151CoreHardGateIntegrationPack();
        var closure = pack.Evaluate(new[]
        {
            new SplitTaskEvidence(173, new[] { "A-013", "A-014", "A-015" }, IsDeterministic: true, IsPassed: true),
            new SplitTaskEvidence(174, new[] { "A-016", "A-017", "A-018", "A-019" }, IsDeterministic: true, IsPassed: true),
            new SplitTaskEvidence(175, new[] { "A-020" }, IsDeterministic: true, IsPassed: true),
        });
        var result = CoreAssertionGateRunner.Run();
        var summary = string.Join("|", result.Records.Select(record => $"{record.AccId}:{record.Message}"));

        closure.IsClosed.Should().BeTrue();
        closure.CompletionSignature.Should().Contain("173:", "integration closure must show deterministic ownership from split task 173");
        closure.CompletionSignature.Should().Contain("174:", "integration closure must show deterministic ownership from split task 174");
        closure.CompletionSignature.Should().Contain("175:", "integration closure must show deterministic ownership from split task 175");
        summary.Should().Contain("A-013");
        summary.Should().Contain("A-020");
    }

    [Fact]
    public void ShouldNotAdvanceClosure_WhenSplitTaskEvidenceIsMissing()
    {
        var pack = new Task151CoreHardGateIntegrationPack();
        var evidence = new[]
        {
            new SplitTaskEvidence(173, new[] { "A-013", "A-014", "A-015" }, IsDeterministic: true, IsPassed: true),
            new SplitTaskEvidence(174, new[] { "A-016", "A-017", "A-018", "A-019" }, IsDeterministic: true, IsPassed: true),
        };

        var result = pack.Evaluate(evidence);

        result.IsClosed.Should().BeFalse("closure must not pass when any required split task evidence is missing");
        result.AdvanceAllowed.Should().BeFalse("closure must not advance when any required split task evidence is missing");
        result.FailureCode.Should().Be("MISSING_SPLIT_TASK_EVIDENCE");
    }

    [Fact]
    public void ShouldProduceDeterministicCoverageSignature_WhenAllSplitTaskEvidenceIsPresent()
    {
        var pack = new Task151CoreHardGateIntegrationPack();
        var evidenceInOrder = new[]
        {
            new SplitTaskEvidence(173, new[] { "A-013", "A-014", "A-015" }, IsDeterministic: true, IsPassed: true),
            new SplitTaskEvidence(174, new[] { "A-016", "A-017", "A-018", "A-019" }, IsDeterministic: true, IsPassed: true),
            new SplitTaskEvidence(175, new[] { "A-020" }, IsDeterministic: true, IsPassed: true),
        };
        var evidenceReordered = new[]
        {
            evidenceInOrder[2],
            evidenceInOrder[0],
            evidenceInOrder[1],
        };

        var firstResult = pack.Evaluate(evidenceInOrder);
        var secondResult = pack.Evaluate(evidenceReordered);

        firstResult.IsClosed.Should().BeTrue("all split tasks 173, 174, and 175 are present with deterministic passing evidence");
        firstResult.AdvanceAllowed.Should().BeTrue();
        firstResult.CoveredAssertions.Should().BeEquivalentTo(RequiredAssertionIds);
        secondResult.IsClosed.Should().BeTrue();
        secondResult.CompletionSignature.Should().Be(firstResult.CompletionSignature, "closure evidence ordering must stay deterministic");
    }

    private sealed class Task151CoreHardGateIntegrationPack
    {
        public IntegrationClosureResult Evaluate(IReadOnlyCollection<SplitTaskEvidence> evidence)
        {
            var evidenceByTask = evidence
                .GroupBy(item => item.SplitTaskId)
                .ToDictionary(group => group.Key, group => group.First());

            var hasAllRequiredSplitTasks = RequiredSplitTaskIds.All(evidenceByTask.ContainsKey);
            if (!hasAllRequiredSplitTasks)
            {
                return IntegrationClosureResult.Fail("MISSING_SPLIT_TASK_EVIDENCE");
            }

            var allPassingAndDeterministic = evidence.All(item => item.IsDeterministic && item.IsPassed);
            if (!allPassingAndDeterministic)
            {
                return IntegrationClosureResult.Fail("NON_DETERMINISTIC_OR_FAILED_SPLIT");
            }

            var coveredAssertions = evidence
                .SelectMany(item => item.CoveredAssertions)
                .Where(item => !string.IsNullOrWhiteSpace(item))
                .Distinct(StringComparer.Ordinal)
                .OrderBy(item => item, StringComparer.Ordinal)
                .ToArray();

            var hasAllRequiredAssertions = RequiredAssertionIds.All(required =>
                coveredAssertions.Contains(required, StringComparer.Ordinal));
            if (!hasAllRequiredAssertions)
            {
                return IntegrationClosureResult.Fail("MISSING_REQUIRED_ASSERTION_COVERAGE", coveredAssertions);
            }

            var completionSignature = string.Join(
                ">",
                evidence
                    .OrderBy(item => item.SplitTaskId)
                    .Select(item => $"{item.SplitTaskId}:{string.Join(",", item.CoveredAssertions.OrderBy(accId => accId, StringComparer.Ordinal))}"));

            return IntegrationClosureResult.Pass(completionSignature, coveredAssertions);
        }
    }

    private sealed record SplitTaskEvidence(
        int SplitTaskId,
        IReadOnlyCollection<string> CoveredAssertions,
        bool IsDeterministic,
        bool IsPassed);

    private sealed record IntegrationClosureResult(
        bool IsClosed,
        bool AdvanceAllowed,
        string? FailureCode,
        string CompletionSignature,
        IReadOnlyCollection<string> CoveredAssertions)
    {
        public static IntegrationClosureResult Fail(string failureCode, IReadOnlyCollection<string>? coveredAssertions = null)
        {
            return new IntegrationClosureResult(
                IsClosed: false,
                AdvanceAllowed: false,
                FailureCode: failureCode,
                CompletionSignature: string.Empty,
                CoveredAssertions: coveredAssertions ?? Array.Empty<string>());
        }

        public static IntegrationClosureResult Pass(string completionSignature, IReadOnlyCollection<string> coveredAssertions)
        {
            return new IntegrationClosureResult(
                IsClosed: true,
                AdvanceAllowed: true,
                FailureCode: null,
                CompletionSignature: completionSignature,
                CoveredAssertions: coveredAssertions);
        }
    }
}
